import stripe

stripe.api_key = 'sk_test_...'

def charge_customer(customer_id: str, amount: Decimal, currency: str = 'usd') -> dict:
    """Charge a customer using Stripe. Returns the charge object."""
    try:
        charge = stripe.Charge.create(
            amount=int(amount * 100),
            currency=currency,
            customer=customer_id,
            description='Invoice payment'
        )
        return {'status': 'success', 'charge_id': charge.id}
    except stripe.error.CardError as e:
        return {'status': 'error', 'message': str(e)}

def refund_charge(charge_id: str) -> bool:
    """Refund a previous charge by charge_id."""
    stripe.Refund.create(charge=charge_id)
    return True

